  "confidence": "moderate",
  "revision_action": "keep",
  "supportive_card_ids": ["C10", "C25", "C47", "C56", "C12", "C72", "C98"],
  "contradictory_card_ids": ["C174", "C135", "C163", "C154", "C64", "C14", "C15", "C16", "C40", "C57"],
  "prediction_basis_card_ids": ["C10", "C25", "C47", "C56", "C12"],
  "claims": [
    {
      "claim": "KNI-272, the closest transferable gold context, showed direct human absolute oral bioavailability of 29.56±3.50% at 4 mg/kg fasted capsule, 33.48% at 6.6 mg/kg fasted capsule, 54.97±19.78% at 10 mg/kg fasted capsule, 33.99±9.73% at 2 mg/kg fasted capsule, and 36.40% at 6.6 mg/kg fed capsule; the query shares the hydroxyethylamine isostere, tert-butyl carboxamide, and cysteine-thioether motif.",
      "card_ids": ["C10", "C25", "C47", "C56", "C12"]
    },
    {
      "claim": "Additional KNI-272 capsule values remained above 20% (31.13±12.98% at 14 mg/kg fasted; 22.06±2.99% at 4 mg/kg fed), while cherry-syrup formulations lowered F to about 15-20%, indicating formulation sensitivity rather than a scaffold-level F<20% outcome.",
      "card_ids": ["C72", "C98", "C64", "C75", "C89"]
    },
    {
      "claim": "L3 saquinavir records show low unboosted oral exposure (Cmax 0.90 µg/mL, AUC 4.60 µg·h/mL at 800 mg BID) with a large ritonavir boost, a caution for the shared decahydroisoquinoline tert-butyl amide; however, these are exposure-only records without an IV comparator, and the query's N-terminus resembles KNI-272 more than saquinavir.",
      "card_ids": ["C174", "C135", "C163", "C154"]
    },
    {
      "claim": "Other L3 oral-exposure records for atazanavir, indinavir, darunavir, and amprenavir show substantial oral Cmax/AUC, consistent with oral absorbability of this peptidomimetic protease-inhibitor class.",
      "card_ids": ["C149", "C138", "C128", "C131", "C126", "C166", "C167"]
    },
    {
      "claim": "The only clearly sub-20% human context, alvimopan at about 6% F, is structurally unrelated to the query and does not transfer.",
      "card_ids": ["C14", "C15", "C16", "C40", "C57"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C174", "C135", "C163", "C154", "C149", "C138", "C128", "C131", "C126", "C166", "C167"]
    }
  ],
  "evidence_gaps": [
    "No direct oral bioavailability measurement exists for the query molecule.",
    "L3 exposure records lack IV comparators, so they cannot quantify absolute F.",
    "The effects of the query's S-benzyl thioether, methylsalicyloyl group, and decahydroisoquinoline on CYP3A4/P-gp first-pass handling are not directly measured.",
    "Formulation and prandial effects for the query are unknown; KNI-272 syrup data show F can approach 15-20%."
  ],
  "decision_summary": "Predicted high because the closest transferable gold context, KNI-272, has direct human absolute F of 22-55% for capsule formulations and the query shares the hydroxyethylamine/tert-butyl amide/cysteine-thioether scaffold. L3 oral-exposure records are mostly boosted PI regimens and do not provide F; saquinavir's low unboosted exposure is a caution but is exposure-only and less transferable than KNI-272. No affirmative threshold-relevant evidence supports F<20% for the query."
}

